css:
.print-container {
        font-family: "Segoe UI", Tahoma, Geneva, Verdana, sans-serif;
        font-size: 12px;
        color: #333;
        line-height: 1.4;
    }

    /* Header Section */
    .header-section {
        margin-bottom: 20px;
    }
    .header-table {
        border-collapse: collapse;
    }
    .company-details {
        vertical-align: top;
        padding-right: 30px;
    }
    .company-name {
        font-size: 20px;
        font-weight: 700;
        color: #2c3e50;
        margin-bottom: 4px;
    }
    .company-address {
        font-size: 11px;
        color: #666;
        margin-bottom: 3px;
    }
    .company-contact {
        font-size: 11px;
        color: #666;
    }
    .document-info {
    vertical-align: top;
    text-align: right;
}
.doc-details-table {
    width: auto;
    margin-left: auto;
    margin-right: 0;
}
.doc-details-table td {
    padding: 2px 5px;
    vertical-align: top;
    font-size: 11px;
}
.doc-details-table td.text-right {
    text-align: right;
    color: #666;
    padding-right: 8px;
}
.doc-details-table td.text-left {
    text-align: left;
    padding-left: 0;
}
    .document-title {
        font-size: 24px;
        font-weight: 700;
        color: #2c3e50;
        margin-bottom: 10px;
    }
    .doc-details-table td {
        padding: 2px 5px;
        vertical-align: top;
        font-size: 11px;
    }
    .doc-details-table td:first-child {
        text-align: right;
        color: #666;
    }
    .header-divider {
        height: 3px;
        background: linear-gradient(90deg, #3498db, #2c3e50);
        margin-top: 10px;
        border: none;
    }

    /* Status Badge */
    .status-badge {
        display: inline-block;
        padding: 2px 8px;
        border-radius: 12px;
        font-size: 10px;
        font-weight: 600;
        text-transform: uppercase;
        letter-spacing: 0.5px;
    }
    .status-badge.draft { background: #95a5a6; color: white; }
    .status-badge.not-started { background: #3498db; color: white; }
    .status-badge.in-progress { background: #f39c12; color: white; }
    .status-badge.completed { background: #27ae60; color: white; }
    .status-badge.cancelled { background: #e74c3c; color: white; }

    /* Summary Section */
    .summary-section {
        margin-bottom: 25px;
        background: #f8f9fa;
        border-radius: 8px;
        padding: 15px;
    }
    .summary-table {
        border-collapse: collapse;
    }
    .summary-item {
        text-align: center;
        padding: 0 15px;
        border-right: 1px solid #dee2e6;
    }
    .summary-item:last-child {
        border-right: none;
    }
    .summary-label {
        font-size: 11px;
        color: #666;
        margin-bottom: 5px;
        text-transform: uppercase;
        letter-spacing: 0.5px;
    }
    .summary-value {
        font-size: 18px;
        font-weight: 700;
        color: #2c3e50;
    }

    /* Sections */
    .section {
        margin-bottom: 25px;
    }
    .section-header {
        background: #f2f2f2;
        color: #222;
        padding: 8px 12px;
        border-radius: 5px 5px 0 0;
        margin-bottom: 0;
    }
    .section-header h3 {
        margin: 0;
        font-size: 14px;
        font-weight: 600;
        text-transform: uppercase;
        letter-spacing: 0.5px;
    }

   /* Minimal Data Table */
.data-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 12px;
    color: #333;
}

.data-table th {
    background: #f2f2f2; /* medium-light gray */
    color: #222;
    padding: 8px 6px;
    font-weight: 600;
    text-align: left;
    border: 1px solid #ddd;
}

.data-table td {
    background: #fafafa; /* light gray for rows */
    padding: 8px 6px;
    border: 1px solid #eee;
    vertical-align: middle;
}

.data-table tbody tr:nth-child(even) td {
    background: #f5f5f5; /* slightly darker gray for alternates */
}

.data-table tbody tr:hover td {
    background: #f0f0f0;
}


    /* Number formatting */
    .number-cell {
        font-family: 'Courier New', monospace;
        font-weight: 600;
        font-size: 11px;
    }
    .pending-qty {
        color: #e74c3c;
        font-weight: bold;
    }
    .bom-code {
        font-family: 'Courier New', monospace;
        font-size: 10px;
        color: #666;
    }

    /* Text alignment */
    .text-right { text-align: right; }
    .text-center { text-align: center; }
    .text-left { text-align: left; }

    /* No Data States */
    .no-data {
        padding: 20px;
        color: #999;
        font-style: italic;
        text-align: center;
    }
    .no-data-message {
        text-align: center;
        padding: 40px 20px;
        background: #f8f9fa;
        border: 1px solid #dee2e6;
        border-top: none;
        border-radius: 0 0 5px 5px;
    }
    .no-data-icon {
        font-size: 32px;
        margin-bottom: 10px;
        opacity: 0.5;
    }
    .no-data-text {
        color: #666;
        font-style: italic;
    }

    /* Footer */
    .footer {
        margin-top: 30px;
        padding-top: 10px;
        border-top: 2px solid #bdc3c7;
    }
    .footer-content {
        text-align: center;
    }
    .print-timestamp {
        font-size: 10px;
        color: #7f8c8d;
    }

    @media print {
        .print-container {
            font-size: 11px;
        }
        .section-header,
        .data-table th {
            -webkit-print-color-adjust: exact;
            print-color-adjust: exact;
        }
        .summary-section {
            background: #f8f9fa !important;
        }
    }
